'use client';
// Public components and save boundary only; mounted exclusively in a tool container.
import {useCallback,useEffect,useRef,useState} from 'react';import AnchoredPopover from '../components/elements/anchored-popover';import {FloatingPanelProvider,useFloatingPanel,type PanelBody} from '../components/elements/floating-panel';import EditSession from '../components/elements/edit-session';import FormField from '../components/elements/form-field';import {EditNavigationProvider} from '../components/elements/edit-navigation';import type {Save,SaveResult,Verification} from '../../../../shared/editor.mjs';
type Fields={name:string};
export default function Page(){const [mounted,setMounted]=useState(true),[requests,setRequests]=useState<number[]>([]),[commits,setCommits]=useState<string[]>([]),pending=useRef(new Map<number,{resolve:(result:SaveResult<Fields>)=>void;attemptId:string;values:Fields}>()),receipts=useRef(new Map<string,Verification<Fields>>()),sequence=useRef(0);
 const save=useCallback<Save<Fields>>((values,_signal,{attemptId})=>new Promise(resolve=>{const id=++sequence.current;pending.current.set(id,{resolve,attemptId,values:{...values}});receipts.current.set(attemptId,{kind:'unknown'});setRequests(old=>[...old,id]);}),[]),verify=useCallback(async(receipt:{attemptId:string})=>receipts.current.get(receipt.attemptId)??{kind:'unknown' as const},[]),commit=useCallback((value:string)=>setCommits(old=>[...old,value]),[]);
 useEffect(()=>{const control=(event:Event)=>{const d=(event as CustomEvent).detail,p=pending.current.get(d.id);if(d.kind==='resolve'&&p){const result=d.result??{kind:'saved',values:p.values};p.resolve(result);receipts.current.set(p.attemptId,result.kind==='saved'?result:{kind:'not-applied'});}if(d.kind==='unmount')setMounted(false);if(d.kind==='remount')setMounted(true);if(d.kind==='ending')dispatchEvent(new Event('templux:session-ending'));};window.addEventListener('fixture:overlay',control);return()=>window.removeEventListener('fixture:overlay',control);},[]);
 return <main><h1>Overlay lifecycle fixture</h1><output aria-label="overlay requests">{JSON.stringify(requests)}</output><output aria-label="overlay commits">{JSON.stringify(commits)}</output><EditNavigationProvider>{mounted&&<FloatingPanelProvider><Controls save={save} verify={verify} commit={commit}/></FloatingPanelProvider>}</EditNavigationProvider></main>;
}
function Controls({save,verify,commit}:{save:Save<Fields>;verify:(receipt:{attemptId:string})=>Promise<Verification<Fields>>;commit:(value:string)=>void}){const panel=useFloatingPanel(),[mode,setMode]=useState('normal'),[counter,setCounter]=useState(0);const open=(id:string,origin?:HTMLElement)=>panel.open({id,title:'Panel '+id,content:(ctx:PanelBody)=><><p className="panel-probe-caption">Synthetic panel content outside the drag handles.</p><AnchoredPopover identity={"panel-help-"+id} label="Panel help" title="Panel auxiliary"><p>Nested auxiliary content</p></AnchoredPopover><EditSession targetKey={id} title="Synthetic edit" manageFocus={false} registerClose={ctx.registerClose} onClose={ctx.requestClose} options={{initial:{name:'Initial '+id},normalize:v=>({...v}),validate:v=>v.name?{}:{name:'Required'},failureMessage:'Synthetic failure',timeoutMs:mode==='timeout'?1000:10000,timeoutMessage:'Result unconfirmed'}} fields={({editor,state})=><FormField label="Panel value" error={state.errors.name}>{attrs=><input {...attrs} name="panelValue" value={state.values.name} onChange={event=>editor.change('name',event.target.value)} onBlur={()=>editor.blur('name')}/>}</FormField>} save={save} verify={verify} onCommit={values=>commit(id+':'+values.name)}/>{Array.from({length:15},(_,i)=><p key={i}>Synthetic scroll content {i+1}</p>)}</>},origin);
 useEffect(()=>{const control=(event:Event)=>{const d=(event as CustomEvent).detail;if(d.kind==='open')open(d.target);if(d.kind==='close')panel.close();};window.addEventListener('fixture:overlay',control);return()=>window.removeEventListener('fixture:overlay',control);});
 return <><div style={{position:'fixed',left:8,top:8,zIndex:5}}><button type="button" onClick={()=>setCounter(n=>n+1)}>Outside count <output aria-label="outside count">{counter}</output></button></div><div style={{height:60}}/><div className="anchor-scroll-test" style={{height:180,overflow:'auto',border:'1px solid',marginBottom:20}}><div style={{padding:'70px 20px 200px'}}><AnchoredPopover identity="fixture-help" label="Open help" title="Synthetic help"><p>Auxiliary information</p><a href="#overlay-openers">Local destination</a></AnchoredPopover></div></div><div id="overlay-openers"><button type="button" onClick={event=>open('A',event.currentTarget)}>Open A</button><button type="button" onClick={event=>open('B',event.currentTarget)}>Open B</button><button type="button" onClick={()=>panel.close()}>Close outside</button><label>Mode<select name="overlayMode" value={mode} disabled={!!panel.currentId} onChange={event=>setMode(event.target.value)}><option value="normal">Normal</option><option value="timeout">Timeout</option></select></label></div><output aria-label="current panel">{panel.currentId??'none'}</output><div style={{height:1000}}/></>;
}
